<?php
require_once __DIR__.'/includes/functions.php';require_login();$page_title='My orders';$s=db()->prepare('SELECT * FROM orders WHERE user_id=? ORDER BY created_at DESC');$s->execute([current_user()['id']]);$orders=$s->fetchAll();include __DIR__.'/includes/header.php'; ?>
<div class="container py-5"><span class="eyebrow">Your StyleCart</span><h1 class="section-title mt-2 mb-4">My orders</h1><?php if(!$orders): ?><div class="py-5 text-center"><h3>No orders yet</h3><a class="btn btn-dark mt-3" href="<?= e(url('products.php')) ?>">Shop now</a></div><?php else: ?><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Order</th><th>Date</th><th>Total</th><th>Payment</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td><strong><?= e($o['order_number']) ?></strong></td><td><?= e(date('d M Y',strtotime($o['created_at']))) ?></td><td><?= money($o['total']) ?></td><td><?= e(strtoupper($o['payment_method'])) ?><br><small class="muted"><?= e($o['payment_status']) ?></small></td><td><span class="badge text-bg-light"><?= e(ucfirst($o['status'])) ?></span></td><td><a class="text-decoration-underline" href="<?= e(url('order.php?id='.(int)$o['id'])) ?>">Track order</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div><?php include __DIR__.'/includes/footer.php'; ?>
